import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = getInputAsList(scanner, Integer::parseInt);
        int n = input[0];
        int mod = input[1];

        int[] dp = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = 0;
        }
        int totalSum = 1;
        dp[1] = 1;

        for (int i = 2; i <= n; i++) {
            int maxF = (int) Math.sqrt(i) + 1;
            int current = totalSum;

            for (int f = 2; f < maxF; f++) {
                current = (current + dp[i / f]) % mod;
            }

            int end = i;
            for (int j = 1; j <= i / maxF; j++) {
                int nextValue = i / (j + 1);
                current = (current + (end - nextValue) * dp[j]) % mod;
                end = nextValue;
            }

            totalSum = (totalSum + current) % mod;
            dp[i] = current;
        }

        System.out.println(dp[n]);
        scanner.close();
    }

    private static int[] getInputAsList(Scanner scanner, java.util.function.Function<String, Integer> parser) {
        String[] parts = scanner.nextLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = parser.apply(parts[i]);
        }
        return result;
    }
}

